import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { defineConfig } from 'vite';

// The HTML pages are generated by scripts/pages.ts (run before every build and dev server);
// it writes the list of entry points to pages.json.
const pages = JSON.parse(readFileSync(resolve(__dirname, 'pages.json'), 'utf8')) as string[];

// In development, forward /ign/* to the IGN like the production nginx does (without the cache).
const ign = {
  '/ign/wms': { target: 'https://www.ign.es', changeOrigin: true, rewrite: (p: string) => p.replace('/ign/wms', '/wms/pnoa-historico') },
  '/ign/wmts': { target: 'https://www.ign.es', changeOrigin: true, rewrite: (p: string) => p.replace('/ign/wmts', '/wmts/pnoa-ma') },
  '/ign/base': { target: 'https://www.ign.es', changeOrigin: true, rewrite: (p: string) => p.replace('/ign/base', '/wmts/ign-base') },
  '/ign/geocoder': { target: 'https://www.cartociudad.es', changeOrigin: true, rewrite: (p: string) => p.replace('/ign/geocoder', '/geocoder/api/geocoder') },
};

export default defineConfig({
  build: { target: 'es2022', chunkSizeWarningLimit: 1200, rollupOptions: { input: pages.map((p) => resolve(__dirname, p)) } },
  server: { proxy: ign },
  preview: { proxy: ign },
});
